// app/projetos/page.tsx -- Server Component (padrao)
async function buscarProjetos() {
  // simula uma busca (no Modulo 6, isso vira uma consulta real)
  return [
    { id: 1, titulo: "Portfolio Pessoal", tecnologias: ["React", "Next.js"] },
  ];
}

export default async function Projetos() {
  const projetos = await buscarProjetos();

  return (
    <main>
      <h1>Meus Projetos</h1>
      {projetos.map((p) => (
        <p key={p.id}>{p.titulo}</p>
      ))}
    </main>
  );
}

"use client";

import { useState } from "react";

function Contador() {
  const [contagem, setContagem] = useState(0);

  return (
    <button onClick={() => setContagem(contagem + 1)}>
      Cliquei {contagem} vezes
    </button>
  );
}

export default Contador;

// app/projetos/page.tsx -- Server Component
import BotaoFavoritar from "@/components/BotaoFavoritar"; // Client

async function buscarProjetos() {
  return [{ id: 1, titulo: "Portfolio Pessoal" }];
}

export default async function Projetos() {
  const projetos = await buscarProjetos();

  return (
    <main>
      {projetos.map((p) => (
        <div key={p.id}>
          <h2>{p.titulo}</h2>
          <BotaoFavoritar />
        </div>
      ))}
    </main>
  );
}
